const body = $input.first().json.body || $input.first().json;

const source = body.source || body.system || 'Core Network Gateway';
const rawAlert = body.rawAlert || body.message || 'Mất kết nối hoàn toàn tới máy chủ cơ sở dữ liệu chính (DB-PROD-01)';
const severityHint = body.severity || 'Unknown';

const incidentId = `INC-${Math.floor(100000 + Math.random() * 900000)}`;

return {
  incidentId,
  source,
  rawAlert,
  severityHint,
  detectedAt: new Date().toISOString()
};

