parameters.jsCode:
const prev = $('Validate & Prepare Alert').first().json;
const aiRaw = $input.first().json;

let text = '';
if (aiRaw.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = aiRaw.candidates[0].content.parts[0].text;
} else {
  text = JSON.stringify(aiRaw);
}

text = text.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    severity: "P1-Critical",
    blastRadius: "Hệ thống bị gián đoạn",
    mitigationSteps: ["Kiểm tra server", "Liên hệ quản trị viên"],
    telegramAlert: `🚨 [BÁO ĐỘNG P1] Sự cố tại ${prev.source}: ${prev.rawAlert}`
  };
}

return {
  incidentId: prev.incidentId,
  source: prev.source,
  rawAlert: prev.rawAlert,
  severity: parsed.severity || "P1-Critical",
  blastRadius: parsed.blastRadius || "Nghiêm trọng",
  mitigationSteps: parsed.mitigationSteps || [],
  telegramAlert: parsed.telegramAlert || `Cảnh báo sự cố: ${prev.rawAlert}`,
  status: "Active - Investigating",
  createdAt: new Date().toISOString()
};

